const REFRACTION_SUBTOPIC = 'Refractive errors and optics'
const KERATOCONUS_SUBTOPIC = 'Keratoconus'
const CATARACT_SUBTOPIC = 'Cataract'
const CORNEA_SUBTOPIC = 'Corneal disease and keratoplasty'
